import {useCallback,useEffect,useMemo,useRef,useState} from 'react';
import {Activity,ArrowDown,ArrowLeft,ArrowRight,ArrowUp,Box,Boxes,Check,CheckCheck,CheckCircle2,ChevronDown,ChevronRight,Clock3,Copy,Download,ExternalLink,FileBox,FileCheck2,FilePlus2,FileUp,Film,FolderOpen,GitBranch,GripVertical,HelpCircle,History,Info,Layers3,LayoutDashboard,Link2,ListOrdered,LoaderCircle,Maximize2,MoreHorizontal,Pause,Play,Plus,RefreshCw,Save,Search,Settings2,ShieldCheck,SkipBack,SkipForward,Sparkles,Trash2,TriangleAlert,Upload,Workflow,X} from 'lucide-react';
import Scene from './Scene';
