 {modal==='flexible'&&<FlexibleReview operations={operations} disabled={!!busy||plan.status==='confirmed'} onSave={async fields=>{const result=await action('save_exception',fields,'입력 범위를 한정한 현장 검토를 저장했습니다. 전체 재검증하세요.');if(result)setModal('');return result;}}/>}
